const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region (Namibia, Botswana, Lesotho)
  const namibia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Namibia'));
  const botswana = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Botswana'));
  const lesotho = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Lesotho'));

  const region = namibia.merge(botswana).merge(lesotho).geometry();

  // 2. Get CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // 3. Calculate Dec 2018 + Jan 2019 total rainfall
  const target = chirps
    .filter(ee.Filter.date('2018-12-01', '2019-02-01'))
    .select('precipitation')
    .sum();

  const targetSize = chirps.filter(ee.Filter.date('2018-12-01', '2019-02-01')).size().getInfo();
  console.log(`Target period images: ${targetSize}`);

  if (targetSize === 0) {
    console.log('No data for Dec 2018 - Jan 2019');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate long-term average for Dec+Jan (2000-2019)
  const years = ee.List.sequence(2000, 2019);

  const decJanTotals = ee.ImageCollection.fromImages(
    years.map(function(year) {
      const startDate = ee.Date.fromYMD(year, 12, 1);
      const endDate = startDate.advance(2, 'month');
      return chirps
        .filter(ee.Filter.date(startDate, endDate))
        .select('precipitation')
        .sum()
        .set('year', year);
    })
  );

  const longTermSize = decJanTotals.size().getInfo();
  console.log(`Long-term period collections: ${longTermSize}`);

  if (longTermSize === 0) {
    console.log('No long-term data available');
    console.log('<answer>C1</answer>');
    return;
  }

  const longTermAvg = decJanTotals.mean();

  // 5. Calculate regional statistics
  const targetStats = target.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  });

  const longTermStats = longTermAvg.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  });

  const targetMean = targetStats.get('precipitation_mean').getInfo();
  const targetCount = targetStats.get('precipitation_count').getInfo();
  const longTermMean = longTermStats.get('precipitation_mean').getInfo();
  const longTermCount = longTermStats.get('precipitation_count').getInfo();

  console.log(`Target (Dec18-Jan19) mean rainfall: ${targetMean !== null ? targetMean.toFixed(2) : 'null'} mm, pixels: ${targetCount}`);
  console.log(`Long-term avg (2000-2019) mean rainfall: ${longTermMean !== null ? longTermMean.toFixed(2) : 'null'} mm, pixels: ${longTermCount}`);

  // 6. Validation
  if (targetCount === 0 || longTermCount === 0) {
    console.log('No valid pixels in region');
    console.log('<answer>C2</answer>');
    return;
  }

  if (targetMean === null || longTermMean === null || 
      isNaN(targetMean) || isNaN(longTermMean) ||
      targetMean < 0 || longTermMean < 0) {
    console.log('Invalid calculation result');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Final comparison
  console.log(`Comparison: ${targetMean.toFixed(2)} vs ${longTermMean.toFixed(2)}`);

  if (targetMean < longTermMean) {
    console.log('Dec18-Jan19 received LESS rain than long-term average');
    console.log('<answer>A</answer>');
  } else {
    console.log('Dec18-Jan19 received MORE or EQUAL rain than long-term average');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
